// 资源预览地址的拼装。
//
// 独立成模块是为了可单测: `.svelte` 组件不能具名导出, 而这段逻辑错一个路径段就是全线 404,
// 构建与类型检查都看不出来。

/**
 * 把"相对 `game/` 的逻辑路径"拼成预览站点上的可访问地址。
 *
 * ⚠️ **`game/` 这一段不能省**: 预览服务器把**项目根**挂成站点根, 而 `base` 里的
 * `.../game/{hash}/s/` 只是站点对外的会话前缀, 不能替代磁盘路径里的 `game/`。
 *
 * @param base 预览站点前缀, 形如 `http://127.0.0.1:PORT/{hash}/s/`; 为 null 表示站点还没起
 * @param rel  相对 `game/` 的路径, 允许用反斜杠 (Windows 来的路径)
 */
export function assetUrlFor(base: string | null | undefined, rel: string): string | undefined {
  if (!base) return undefined;
  const normalized = rel.replace(/\\/g, '/').replace(/^\/+/, '');
  // 逐段 `encodeURIComponent`: 文件名里的 `#`、`?`、`%`、空格不编码会被当成 URL 的分隔符,
  // 请求打不中文件 (缩略图裂图 / 预览空白)。
  return `${base}game/${normalized.split('/').map(encodeURIComponent).join('/')}`;
}
